---@class ActivityCakeDojo
local ActivityCakeDojo = Class("ActivityCakeDojo")

function ActivityCakeDojo:__init()
    self.hp = {}
    self.entranceConf = {}   ---
    self.scheduleConf = {}   ---排期数据
    self.mainQuestMap = {}   ---主线数据
    self.luckyDrawInfo = {}
    self.nowPoolId = 0       ---当前解锁到了那个商店
    self.mainQuestId = 0     ---当前通关的ID
    self.taskTips = -1       ---任务红点
    self.bossTips = -1       ---Boss小红点
    self.luckyDrawTips = -1  ---抽奖小红点
end

---FillVo
---@param row TableML.TableFileRow
function ActivityCakeDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            if key == "mainQuestMap" then
                for i, v in pairs(value) do
                    if checkNumber(v.unlockCountdown) > 0 then
                        v.unlockCountdown = v.unlockCountdown + os.time()
                    end
                end
            end
            self[key] = value
        end
    end
end

function ActivityCakeDojo:GetMainLineData()
    return self.mainQuestMap
end

function ActivityCakeDojo:GetShopData()
    return self.luckyDrawInfo
end

function ActivityCakeDojo:UpdateItemStockAndPool(stocks,index,nowPoolId)
    local data = self.luckyDrawInfo[index]
    for k, v in pairs(data.list) do
        if v.stock > 0 and stocks[tostring(v.id)] then
            v.currentStock = stocks[tostring(v.id)]
        end
    end
    self.nowPoolId = nowPoolId
end

function ActivityCakeDojo:IsBtnUnLock(id)
    for i, v in pairs(self.entranceConf) do
        if v.id == id then
            return self.mainQuestId >= checkNumber(v.unlockLevel)
        end
    end
    return true
end

function ActivityCakeDojo:GetModuleId(id)
    for i, v in pairs(self.entranceConf) do
        if v.id == id then
            return v.moduleId
        end
    end
    return true
end



function ActivityCakeDojo:GetUnLockChapterId(id)
    for i, v in pairs(self.entranceConf) do
        if v.id == id then
            return checkNumber(v.unlockLevel)
        end
    end
    return 0
end

function ActivityCakeDojo:GetMainChapterId()
    return checkNumber(self.mainQuestId)
end

function ActivityCakeDojo:GetHp()
    return self.hp.hp
end

function ActivityCakeDojo:UpdateInfo(data)
    self.hp.hp = data.activityHp
    self.mainQuestId = data.newMainQuestId
end

function ActivityCakeDojo:GetBossTips()
    return self.bossTips
end

function ActivityCakeDojo:GetLuckyDrawTips()
    return self.luckyDrawTips
end

function ActivityCakeDojo:UpdateRedPoint(isCan)
    local num = isCan and 0 or -1
    if num ~= self.bossTips then
        self.bossTips = num
        Events.Broadcast(Constants.EventNames.CommonActivityBossHurtTipsChanged)
    end
end

function ActivityCakeDojo:IsUnLockShop(id)
    return self.nowPoolId >= id
end

function ActivityCakeDojo:GetNowPoolId()
    return self.nowPoolId
end

function ActivityCakeDojo:GetScheduleConfig()
    return self.scheduleConf
end

function ActivityCakeDojo:__delete()
    self.hp = nil
    self.entranceConf = nil
    self.scheduleConf = nil
    self.mainQuestMap = nil
    self.mainQuestId = nil
    self.luckyDrawInfo = nil
    self.nowPoolId = nil
    self.taskTips = nil
    self.bossTips = nil
end

return ActivityCakeDojo